defmodule AshPhoenixStarter.Farms.FarmPlanting do
  use Ash.Resource,
    domain: Elixir.AshPhoenixStarter.Farms,
    data_layer: AshPostgres.DataLayer

  postgres do
    table "farm_plantings"
  end

  multitenancy do
    strategy :context
  end

  preparations do
    prepare AshPhoenixStarter.Preparations.SetTenant
  end

  changes do
    change AshPhoenixStarter.Changes.SetTenant
  end

  attributes do
    # Primary Key generated by Postgres via uuid_generate_v7()
    uuid_primary_key :id do
      generated? true
      allow_nil? true
      writable? false
    end

    attribute :planting_date, :date do
      allow_nil? false
      public? true
    end

    attribute :expected_harvest_date, :date do
      allow_nil? false
      public? true
    end

    attribute :quantity_planted, :float do
      allow_nil? false
      public? true
    end

    # Database-managed timestamps
    attribute :inserted_at, :utc_datetime_usec do
      generated? true
      allow_nil? true
      writable? false
    end

    attribute :updated_at, :utc_datetime_usec do
      generated? true
      allow_nil? true
      writable? false
    end
  end

  relationships do
    # CHANGED: Now explicitly references FarmField instead of Field
    belongs_to :field, AshPhoenixStarter.Farms.FarmField do
      attribute_type :uuid
      public? true
    end

    # Required relationship based on null: false in migration
    belongs_to :crop, AshPhoenixStarter.Farms.FarmCrop do
      attribute_type :uuid
      allow_nil? false
      public? true
    end
  end

  actions do
    defaults [:read, :destroy]

    create :create do
      primary? true
      accept [:planting_date, :expected_harvest_date, :quantity_planted, :field_id, :crop_id]
    end

    update :update do
      primary? true
      accept [:planting_date, :expected_harvest_date, :quantity_planted, :field_id, :crop_id]
    end
  end
end
